PACK = [
    # ---------------- Holidays, just 3 a ninth time (holidays age-3 primary 12 -> 13; the floor) ----------------
    A("big-groundhog-shadow-morning-look", "Big Groundhog Shadow Morning Look",
      "February the second: a soft groundhog peeks out of its burrow box, and the whole group checks the sunny patch — is anybody's shadow out today?",
      ["holidays"], (3, 3), (3, 14), (10, 15), ["indoor", "outdoor"],
      ["one soft toy groundhog (or a brown sock puppet with two ears sewn or tied on — a groundhog the room can greet by name; soft, washed, and big enough to see across a circle)", "one big cardboard burrow box (a box with a round door cut by the adult, big enough for the groundhog to peek from and for nobody to climb into — its door faces the group)", "one sunny patch of ground or floor by a window (the shadow-checking place, found by the adult that same morning; on a grey morning, a bright torch shone across the floor is the honest stand-in and is named as one)"],
      False, "Cut the burrow door yourself and check the box the way this record checks everything: by trying it. The box must stand steady when the groundhog is pushed through its door a dozen times, and its edges must be tape-smooth — a burrow that collapses on its tenant teaches slapstick, not February. That morning — not the day before — stand in the shadow-checking place yourself and learn what kind of morning it is: if the sun is out, your own shadow will be standing there to meet you, and the record will run on the real thing; if the sky is grey wall to wall, set the torch across the floorboards instead and plan to name it honestly in the framing ('the sun is behind the clouds today, so our lamp will hold the sun's job'). Knowing which morning you have before the circle gathers is the whole preparation.",
      ["Gather the group where every eye can see the burrow box and say the plain framing: 'Today is the second of February, and people tell a story about this day — that a groundhog comes out of its burrow, and if it sees its shadow, winter stays a while longer. It is a story people love. It is not a weather report — a groundhog cannot call the spring, and neither can we. But the story is ABOUT something real, and we can check the real thing ourselves: shadows. When the sun is out, shadows come out. When the clouds cover the sun, they do not. Today we check.' State the laws whole: 'The groundhog lives in the adult's hands or in its burrow — it is greeted, never grabbed. Shadow-checking is standing still and looking DOWN: eyes look at the ground, never up at the sun, ever. Reports are given in the day's two words, and both words are good news.'",
       "First peeking together: the burrow door faces the group, the adult's hand goes in slow, and the groundhog comes out the way the story says — nose first, then ears, then the whole round body, blinking at the room. The group greets it by name, and then the record's real question is put to it at full ceremony: 'Groundhog. The story says you look for your shadow. We will help you look — because looking is a job this room is good at.' The groundhog is carried to the shadow-checking place by the adult, held low where a groundhog lives, and the group watches the ground beneath it like a jury: is there a groundhog-shaped shadow on the ground, or is there not?",
       "Shadow-checking round: whatever the groundhog's report, the children check their own, one at a time, standing in the patch at full stillness — feet planted, arms a little out, eyes DOWN at the evidence — while the room calls the finding in the session's official shape: 'SHADOW OUT' (a dark self standing on the ground, waving when its owner waves, which the owner is invited to test exactly once) or 'NO SHADOW' (the ground bare of any second self, the light flat, the clouds holding the whole sky). Both reports are received at identical size, and the record says why while it happens: 'A no-shadow morning is not a broken morning. It is a cloudy one. The groundhog's story works on cloudy mornings too — that is most of why people kept telling it.'",
       "Story stretch, once every checker has a report: the adult tells the last piece plainly, because this record does not let a story borrow science's coat: 'In the story, a shadow means six more weeks of winter. In the real world — the one we just checked with our own eyes — a shadow means the sun is out RIGHT NOW, on this patch of ground. It says nothing about next week. Next week will bring its own mornings, and we will check those too.' Then the group's own morning is named and filed in the day's official sentence, said together: 'On OUR February the second, the report was: SHADOW OUT' (or NO SHADOW) '— seen with our own eyes, on our own ground.'",
       "Finish with the groundhog returned to its burrow at full ceremony — backwards in, the way groundhogs in stories go, to sleep until the story needs it again — and the tell-back said over the closed door: 'The story said a groundhog would look. We looked WITH it, and then we looked for ourselves, every one of us, eyes down, standing still. Whatever the morning was, we know what it was — because we checked. That is worth more than the story, and the story is worth quite a lot.' The burrow box lives on the shelf until spring, and on any sunny morning before then, any child may point at a shadow and file the report again: it stays official all season."],
      "A two-checker version: the groundhog and one volunteer check, the group reports — the whole ceremony inside ten minutes for the newest circles.",
      "A torch version (a grey week, no sun at all): the checking place is a dark corner and a big torch, every child checks by lamplight across several mornings, and the day the real sun finally does the job is celebrated as the record's true February the second, whatever the calendar says.",
      safety="Eyes look down, always: nobody looks at the sun in this record, and the adult says it in the framing and watches for it in the round — a child who tips their face up is brought back to the evidence kindly ('the shadow is down HERE, with us'). The checking patch is walked by the adult that morning for ice, puddles hiding ice, and anything the ground is keeping; standing still is the game's whole motion, and it is done on ground the adult would stand on in socks. The burrow box is adult-cut, tape-smoothed, and furniture, not a toy: nobody climbs in, on, or through it, and a box that softens or tips is retired to the recycling with the groundhog's thanks. The torch stand-in is an adult-held lamp, never passed hand to hand, and its light is shone across the floor — at the ground, like the sun's job requires — never into anybody's eyes.",
      tags=WINTER, copy_free=True, no_elimination=True,
      inclusion="Checking works from any position the patch allows: a seated checker checks from a chair set in the sunny place — a shadow keeps no opinions about the height it is cast from — and a checker's wave can be a raised hand, a turned head, or a held-up scarf, each answered by the shadow identically and reported at the same size. The reports are the record's honours and they come in every register the room owns: spoken, signed, stamped on the floor with one foot for SHADOW OUT, or given by the checker pointing at the group's two big report cards, which the adult holds up one at a time. The groundhog's carrier — walking beside the adult as the tenant travels to the checking place, hands ready under it — is the morning's official second honour and rotates by list."),

    # ---------------- Team & community, just 3 a ninth time (team-community age-3 primary 12 -> 13; the floor) ----------------
    A("big-new-friend-room-tour", "Big New Friend Room Tour",
      "A new friend needs three places first: where the cups live, where the coats hang, and where the quiet is. The group shows all three, pointing and naming.",
      ["team-community"], (3, 3), (4, 14), (10, 20), ["indoor"],
      ["the group's own room, as it stands (the tour's whole territory — its cup shelf, its coat hooks, its quiet corner, in the room's ordinary state, not tidied into a show home)", "one soft friend to be the guest when no real new child is visiting (the class bear or another famous soft resident — carried by a rotating carrier, greeted by name, treated exactly as a guest is treated)"],
      True, "Decide the tour's three places before the group gathers, and decide them the way a three-year-old's first day actually runs: where my cup lives (and whose hands may fetch it), where my coat hangs (and which hook could be mine), and where the quiet is (the corner a person goes to when the room is too much — shown with the same pride as the other two, because knowing where the quiet is, is belonging). Walk the route yourself at child height and child pace: it should take about forty small steps with no squeezing past furniture, no doors the adult must fight, and nothing on the way that a pointing hand could knock into a face. If a real new child is the guest, brief nobody and rehearse nothing: the tour is offered, and watching the whole thing from a safe lap counts as taking it — that rule is set before the guest arrives, not negotiated after.",
      ["Gather the group by the door — the room's threshold, where every arrival stands — and say the plain framing: 'When somebody is new in a room, everything in it is a question. Where does my cup go? Where does my coat hang? Where is the quiet, if I need it? Today we practise answering, the way this room answers: by showing. Our guest —' (the guest is named: the real new child, welcomed at full size, or the bear, presented with identical ceremony) '— will be shown three places by the people who live here. You.' State the laws whole: 'Tours walk. Guides point and name — hands stay kind and off other people's things: we point AT the cup shelf, we do not rearrange it. The guest may look as long as looking takes. Nobody is quizzed at the end: showing is the whole job, and it ends when the showing is done.'",
       "First place together, the cups: the whole tour walks the forty steps at the guest's pace — which is set by the slowest walker without comment — and gathers where the guest can see the shelf properly. Two guides, chosen by list, do the showing in the session's official shape: one points, one names: 'THIS is where the cups live. Yours would go HERE —' (the pointing hand shows the honest spare space, not a space invented for the day) '— and the water is THERE, and an adult helps, always.' If the guest is real and reaches for a cup, the reach is honoured as the tour working, and the adult quietly makes the cup theirs: naming a cup is lovely, but handing it over is the room meaning it.",
       "Second place, the coats, and third, the quiet: the route continues at the same unhurried pace, with the pointing-and-naming passing to fresh guides at each stop so the honours spread around the room — at the hooks: 'Coats hang HERE. This hook is spare. It could be yours in one minute, if you wanted it to be' — and at the quiet corner, the tour's most important stop, the guides say the record's plainest line at full size: 'And THIS is where the quiet is. Anybody may come here. You do not have to ask, and nobody follows you in. It is part of the room, like the cups.' The guest is shown how the corner works — its cushion, its soft thing, its boundary — by a guide sitting in it for three breaths, demonstrating that the corner is used by the room's own people, not reserved for its saddest ones.",
       "Guest's-choice stretch, the tour's heart: the route walked, the guest chooses the place they liked best, and the whole tour goes back to it together — a teddy guest's choice is made by its carrier, at the carrier's own honest preference, and a real guest's choice can also be the door, the window, or nowhere yet, and every one of those is received as a complete answer: 'The door is a good favourite. It is where the room begins.' At the chosen place the group settles for one minute of simply being there together — drinking the pretend tea of arrival, saying nothing that needs saying — because a tour that ends by USING the room together teaches more than the pointing did.",
       "Finish back at the threshold, where tours end: the guest is thanked for visiting ('You let us show you our room. Showing it made it more ours, not less') and the guides are thanked by name for the specific thing each one showed — 'You showed where the quiet is. A new person will remember that longest.' The tell-back is said at the door: 'Three places: where the cups live, where the coats hang, and where the quiet is. Shown by the people who live here, at walking pace, with pointing hands. Whoever arrives in this room next gets this tour — because now this room knows how to give it.' The bear, if it was the guest, keeps a place of honour by the door for the week: the room's greeter, on duty."],
      "A one-place version: only the quiet corner is shown, with full ceremony — the whole record inside ten minutes, for a day when one place is what a real arrival needs.",
      "A photograph version (a real arrival expected next week): the guides pose at each of the three places, the adult photographs the pointing and the naming, and the three pictures wait by the door for the guest who has not come yet — a tour that travels ahead of its guest.",
      safety="The tour stays inside the group's own room, on the route the adult walked at child height first: no toilets, no staff areas, no other rooms, and no door in the route is opened by a child's hands — doors on the way are the adult's, held, every time. Pointing hands point at things, never into faces, and other children's belongings on the route — the cups and coats of the room's own people — are looked at and named, never handled, rearranged, or tried on: a tour that disturbs the room teaches the opposite of welcome, and the adult restores anything touched without comment and without blame. A real guest child is never the tour's exhibit: they walk it, watch it from a lap, or leave it halfway, all at full honour, and the group's excitement is coached in the framing — a new person is shown the room, not surrounded by it.",
      copy_free=True, no_elimination=True,
      inclusion="Guiding divides cleanly into jobs at every distance: the pointer points, the namer names, the carrier carries the guest, the pace-setter walks first and sets the guest's pace — and a guide who travels the room differently still points from their own position, because the three places can be shown from a seat at each stop as truly as from a stance beside them. Naming arrives in any register the room owns: spoken, signed, tapped on the place itself, or given by the guide holding up the room's picture of the place while the adult speaks the name the guide has chosen — the credit for the showing stays the guide's in the tell-back, by name. The guest's honours are sized to the guest: a real new child who says nothing all tour and then chooses the quiet corner has taken the tour at its deepest, and the record receives it that way."),

    # ---------------- Seasons, just 3 a ninth time (seasons age-3 primary 13 -> 14; summer tag) ----------------
    A("big-sandcastle-one-bucket-towers", "Big Sandcastle, One Bucket Towers",
      "Wet sand, one big bucket, pat-pat-turn: a tower stands. Dry sand runs through your fingers — wet sand stands up. That is the whole summer science, built.",
      ["seasons"], (3, 3), (2, 12), (15, 20), ["outdoor"],
      ["a sand place with sand that can be wetted (a sandbox, sandpit, or a stretch of beach sand the adult has checked — plus a bucket of water and a small watering can for keeping it at building dampness)", "big buckets, one per builder at a time (sturdy, smooth-rimmed, big enough that a tower made from one is worth decorating)", "big scoops for filling (short-handled, blunt — a scoop that bends under wet sand is retired before it teaches frustration)", "found decorations (shells, smooth pebbles, sticks and fallen leaves gathered from the sand place itself — adult-checked, nothing sharp, nothing that was living in it)"],
      False, "Wet the sand yourself before anyone is called and learn its temper with your own hands: pack a bucket, turn it, lift — if the tower comes out whole, the sand is at building dampness; if it slumps, add water a can at a time and test again, because at three the difference between a castle and a disappointment is a watering can nobody used in time. Check the whole sand place the way the season demands: rake through it with the scoop for anything buried that small hands should not find (glass, sharp shells, the leavings of other people's picnics), and check its temperature with the back of your hand — summer sand in full noon sun can be too hot for the knees that will kneel in it, and a shaded corner or a morning hour is this record's honest fix. Set the water bucket where its spills do the sand good, not the path.",
      ["Gather the builders at the sand's edge and say the plain framing: 'Summer gives us sand and water, and together they do a trick. Dry sand — watch —' (let a handful run through your fingers, all of it, to the last grain) '— runs away. It cannot stand. But wet sand —' (pack the bucket as the group's first lesson, pat-pat, turn, lift: a tower) '— STANDS. That is the whole trick, and it is a real one: the water holds the grains together, like tiny hands. Today we build towers out of the holding kind.' State the laws whole: 'Sand stays LOW: it is scooped, carried low, and built with — it is never thrown, and a handful that rises above waist height is set down and the building starts again. Water goes on the SAND, from the can, at the adult's end of the sand place. Castles are built in the building ground, where knees and towers have room — nobody builds in the walking way.'",
       "First tower together, yours: fill the big bucket at full ceremony — scoop, scoop, scoop — with the room counting the scoops because filling is the record's rhythm section, then pat the top flat with two flat hands (pat-pat, all over, the tower's roof being made level before it exists), choose the tower's ground together, turn the bucket over in one honest motion, pat its bottom twice — the tower-maker's knock — and lift straight up, slow, while the room holds the hush the moment deserves. Whether it stands whole or slumps at one corner, the report is given in the session's official shape: 'ONE tower standing' — or 'One tower SLUMPED — its sand was too dry at the corner. The corner told us. We shall wet it and build it again, exactly there.' A first slump, read kindly, teaches more than a first success; the record does not arrange either, it reads both.",
       "Building round: builders take the bucket in known order, one tower each, along the building ground — fill, pat, turn, knock, lift — while the waiting builders keep the sand at building dampness with the can (a job with its own ceremony: 'Wetting crew — the corner by the standing tower looks thirsty') and the room counts the castle as it grows: 'THREE towers standing.' A tower that falls to its own builder's lift is that builder's to rebuild on the spot with wetter sand and the room's full patience; a tower that stands gets its flag moment — a stick stood in its top by its own builder, at whatever angle the sand allows — so the skyline of finished work is visible from the counting place.",
       "Decorating stretch, once the towers stand in their row or their ring: the found decorations come out in the adult's flat tray, and builders dress their own towers — a shell pressed flat into the wall like a window, a pebble path laid grain by grain to the door that isn't there, a leaf flying from the flag-stick — while the record's decorating law holds kindly: 'A decoration is PRESSED in, gently. Pressing hard is building backwards.' Towers dressed, the builders walk the counting place view together — the castle from the front, at adult-knee height, in silence for three breaths — because looking at finished work properly is part of building it, and summer afternoons are long enough for both.",
       "Finish with the record's honest ending, said before it happens so it lands as knowledge, not loss: 'Castles are for today. The sand was here before the castle and it will be here after — the towers go back to being a sand place, and everything we learned stays standing in US.' The builders may knock their own towers down — by their own hands, tower by tower, at the count — or leave them standing for the next group to find, and the choice is the builders' and is recorded either way in the tell-back: 'Five towers stood today, because wet sand holds and this room learned how wet. The sand is sand again. The builders are builders for good.' Hands and knees are brushed down at the sand's edge, shoes shaken out over the grass, and the water bucket's last can goes on the building ground — keeping it ready, kindly, for whoever builds tomorrow."],
      "A two-tower version: the adult's tower and one builder's, the full ceremony of fill-pat-turn inside fifteen minutes for the newest builders.",
      "A sand-table version (no outdoor sand place): a deep tray of sand on a table, wetted the same way, towers built small-bucket size — the same science, the same reports, at standing height indoors.",
      safety="Sand stays low, by law, from the first minute: thrown sand ends a builder's turn kindly and immediately, because sand in eyes is this record's one real injury and it is designed out by the rule, not by luck. The sand place is adult-raked before the session for glass, sharp shell, and buried rubbish, and re-checked after any break — and the decorations pass the same adult hand: shells washed and edge-checked, sticks smooth and short, nothing that was living in a shell comes to the building ground at all. Summer rules stand around the record: shade or morning hours for the building ground, hats by the house's ordinary law, water for drinking kept apart from water for wetting — the can is for the sand, the cups are for the builders, and the two never swap jobs. Hands are washed with soap when the building ends; sand under nails is a souvenir the record does not send home in mouths.",
      tags=SUMMER, copy_free=True, no_elimination=True,
      inclusion="Every stage of building has a shape for every builder: the scoop can be two-handed, the pat can be done with a flat palm or the back of a scoop, the turn can be powered by a partner's hands under the direction of the tower's own builder — 'turn... LIFT, slow' — with the tower, and the report, staying the director's. The wetting crew and the decoration tray are full building jobs, not consolation ones: a builder whose whole morning is keeping the sand at building dampness has held the castle's foundation in their hands all session, and the tell-back names it so. Counting can be called from the counting place by the room's counter in any register — spoken, signed, or held up on fingers one tower at a time — and the hush before the lift belongs to everybody equally, from every position around the sand.")]

PACK += [
    # ---------------- STEM, just 3 a ninth time (stem age-3 primary 13 -> 14) ----------------
    A("big-sound-jar-loud-or-soft", "Big Sound Jar, Loud or Soft",
      "Big sealed jars, one shake each: some jars are LOUD and some are SOFT, and the ears of the room file every one on its right mat.",
      ["stem"], (3, 3), (2, 10), (10, 15), ["indoor"],
      ["big sound jars, a filing set of six to eight (big opaque jars with lids the adult has filled, sealed, and tape-locked — the loud ones carrying a few big bells or wooden beads, the soft ones carrying rice or dried lentils; every jar shaken by the adult first, at arm's length, against their own ear)", "two big filing mats (the LOUD mat and the SOFT mat — two floor cards the adult has marked big and clear: a drum drawn on one, a feather on the other; the room learns them before the first jar appears)"],
      False, "Make the jars like an instrument-maker who will be audited by toddlers: fill them in two honest families — loud (two or three big bells, or four wooden beads, in a jar with room to travel) and soft (rice or lentils, a third full, so the sound pours rather than rattles) — then seal every lid, tape it round, and shake each jar yourself at arm's length. Any jar whose sound sits between the families — the maybes — is refilled or retired: at three, the record's filing must be honestly fileable, and a jar that argues with the ears teaches arguing, not listening. Line the jars up in a mixed order you have written down (your own answer key, for the final count), set the two mats a body's width apart on the floor, and learn the drum card and the feather card by heart so you can introduce them without a flicker of doubt: drum is LOUD, feather is SOFT.",
      ["Set the two mats where the whole circle can see them, hold up the cards' meaning first ('This drum means LOUD — a sound that fills the room. This feather means SOFT — a sound that lands like this —' and let a feather of paper fall, if you have one, in the hush) '— and today your ears are the filing clerks.' Say the plain framing: 'These jars are sealed, and they stay sealed — what is inside them is not the lesson, and nobody will open one to check. Inside, some jars carry LOUD sounds and some carry SOFT ones. One shake tells your ears which. Your job: shake once, listen properly, and file the jar on its mat. The jar will not be offended. Jars are professional.' State the laws whole: 'One shake per jar — a good shake, at your chest, never beside anybody's ears, never beside your own. While a jar shakes, the room is quiet: listening is everybody's job, not just the shaker's. A filed jar stays filed until the final count — ears may argue later, at the count, kindly.'",
       "First filing together, yours: take the first jar, hold it where every eye can see it, and shake it once at full ceremony — one shake, no more — while the room does the listening at full size, which at three looks like hands going still and mouths closing by themselves. Give your own ears their moment in the open ('I hear it landing heavy and bright... my ears say LOUD') and file the jar on the drum mat with the session's official report, said whole: 'Jar one: LOUD — filed.' Then the record's honesty is established in the open, because it governs everything after: 'If your ears heard it differently, keep your hearing. At the final count we may argue — kindly, with shakes — and the jars will be re-heard by the whole room. Filing is not finished until the count.'",
       "Filing round: shakers take the jars in known order, one each — shake held at the chest, ONE shake — while the room listens in the official hush and the shaker files the jar on the mat their own ears choose, giving the report in the official shape: 'Jar four: SOFT — filed.' A shaker who cannot decide shakes once more — the record allows exactly one appeal shake, announced as such ('An appeal — ONE more') — because listening again is a scientific act, and then files by their best hearing. The adult guards only the constitution: jars shaken at chests, hush kept kindly ('Clerks — the jar is speaking'), and never, not once, a hint from the adult's face about which mat is right — the adult's face in this record is a sealed jar too.",
       "Borderline stretch, for a room whose ears have grown sharp: the last jar in the set is the adult's planted puzzle — a jar filled to sit nearer the border than its brothers (beads in a fuller jar, their rattle muffled) — introduced honestly as such before it is shaken: 'This last jar is the difficult file. Grown-up clerks argue about jars like this one. Shake it twice — it has earned two — and file it where your ears truly say, and know that the count may move it, and moving it will be the room learning, not the shaker failing.' The argument at its filing is the lesson's summit and is given its time: two hearings, two opinions stated with their evidence ('It landed heavy — but SMALL'), and a filing by the shaker's own final call.",
       "Finish with the final count, the record's audit, conducted like a ceremony because it is one: the jars on each mat are counted aloud — 'The LOUD mat holds four. The SOFT mat holds three' — and then each jar is re-shaken once by its own filer while the whole room confirms or appeals its file with a show of the drum-feather hands (flat palm down for drum, fingers floating down for feather — the room's own signing). A jar the room moves is moved by its filer, with the record's line said over it at full size: 'The room heard it again, and the room knows more than it did. That is not a mistake being fixed. That is ears, working.' The tell-back closes the files: 'Seven jars, shaken once each, filed by ear — loud on the drum, soft on the feather, and one difficult file argued like professionals. Nobody opened a thing. The ears did all of it.' The jars return to their shelf unopened, where their mystery keeps — filed, and faintly audible whenever the shelf is bumped, which the room will notice for weeks."],
      "A four-jar version: two loud, two soft, the whole filing office inside ten minutes for the newest clerks.",
      "A matching version (a room that has filed before): twin jars hide in the set — two jars with the same sound — and after the filing, shakers hunt the pair by ear alone, the mats' work done, the office become a detective agency.",
      safety="The jars are sealed by the adult, tape-locked, and audited before the session and after it: a lid that turns, cracks, or weeps a single grain retires its jar from the set instantly and permanently — the fillings (bells, beads, rice, lentils) are choking hazards the record keeps behind a sealed lid as its first law, and no jar is ever opened in the room, by anyone, for any verdict; the final count argues with shakes, not with evidence. Shaking happens at the shaker's own chest, one shake at a time: never beside ears — anybody's, including the shaker's — and never thrown, dropped on purpose, or rolled across the floor; a jar is carried in two hands between shakings like the instrument it is. Jars are big, light when dropped by accident, and plastic or well-padded: glass has no place in a filing office run by three-year-olds, and the adult's set uses none.",
      copy_free=True, no_elimination=True,
      inclusion="The filing office honours every kind of ear: a clerk who hears with their hands holds each jar against their own flat palm — or lets a partner shake it while both their hands rest on it — and files by the jar's travel, which the loud jars give generously and the soft ones give as a pour; both are real evidence and the final count treats them so. Filing can be done by direction ('the feather mat — THERE'), by pointing at the drum or feather card the adult holds up one at a time, or by the room's signing at the count — and the appeal shake, the office's great dignity, belongs to any clerk on request, requested in any register. The hush-keeper — the clerk whose held-up hand calls the room to listening before each shake — holds the office's official silence and rotates by list from any seat."),

    # ---------------- Icebreakers, just 3 a ninth time (icebreakers age-3 primary 13 -> 14) ----------------
    A("big-choose-your-colour-corner", "Big Choose Your Colour Corner",
      "Four big colours, one in each corner. Walk to the colour you like best today, stand with your colour, and wave to the other corners. Tomorrow may differ.",
      ["icebreakers"], (3, 3), (4, 16), (10, 15), ["indoor"],
      ["four big colour mats, one per corner of the room (red, blue, yellow, green — mats or big cards laid flat and weighted or taped at their corners so no edge can curl under a small foot; the colours are the whole equipment)"],
      True, "Lay the four corners before the group gathers and then walk them yourself, slowly, at three-year-old eye height: each colour must read clearly across the room (a yellow card on a pale floor in bright window light can wash into a rumour — move it into shade or back it with something dark), each corner must have standing room for more children than you expect to choose it — because a colour everybody loves is a crowd, and a crowd in a corner needs its ground planned, not discovered — and the walking lanes between the middle and every corner must be clear of the furniture that migrates into rooms like this. Learn the record's one kindness in advance: you will not balance the corners. If eleven children choose blue, blue holds eleven, and the corner's size is reported as joy, not corrected as a problem.",
      ["Gather the group in the room's middle and say the plain framing: 'Look at the corners. This room is wearing four colours today — red there, blue there, yellow there, green there. In a moment, each of you will walk to ONE colour: the one you like best TODAY. Not forever. Not for a team. Just the colour your eyes are happiest standing in this morning. You will stand with your colour, and your colour's people will stand with you, and we will see what this room likes today.' State the laws whole: 'Choosing is walking — nobody runs to a colour; a colour is worth walking to. Colours are not teams: nobody recruits, nobody persuades, nobody says a colour is wrong — a colour cannot be wrong; it can only be somebody's favourite, or not yours. Changing your mind is allowed — in the second round, anybody may walk to a new colour, and the room will be glad to watch them go.'",
       "First choosing together, yours: name your own colour at full ceremony and walk to it at the record's official pace, talking your choosing out loud the way the room will need to hear choosing done: 'My eyes keep going to the yellow. Yellow is standing in the sun over there and it looks like morning. I am choosing yellow — today. Yesterday I might have chosen blue. Tomorrow is tomorrow's business.' Stand in your corner and be counted there, visibly, an adult alone in a colour with nobody yet beside you — because the room must see that a corner of one is a complete corner before anyone is asked to risk being one.",
       "Choosing round: the group chooses at the adult's word — walking, in all directions at once, the room briefly a slow weather of small people crossing to their colours — and settles. Then the corners are greeted in the session's official ceremony: each corner, in turn, WAVES to the other three and calls its colour ('BLUE corner — here we are!'), and the other corners wave back, because the record's whole sociology is in that wave: different colours, one room, everybody visible to everybody. The counts are taken by the corner-callers and given in the official shape — 'Blue holds five. Red holds two. Yellow holds three. Green holds ONE — and one is a whole corner' — the smallest corner named at exactly the same size as the largest, by design, every time.",
       "Second choosing stretch, the record's heart: after a minute of standing in colour, the adult opens the floor's one great permission: 'Second choosing. Your feet may keep your colour — or they may take you somewhere new, if your eyes have changed their minds while standing here. Changing is not cheating. Changing is looking twice.' Whoever walks, walks at the same unhurried pace, received by their new corner with the wave — and whoever stays is named kindly too ('Some colours hold their people. Staying is also a choice, and the room can see it'). The new counts are taken and the CHANGES are reported as the day's real news, ahead of the numbers: 'Two people changed. One went from red to green because —' (the changer, if they wish, gives their reason in any size: 'Green looked quieter' is a complete philosophy) '— and the room is glad to know it.'",
       "Finish with the whole group walking back to the middle together — colours dissolving kindly into the room again — and the tell-back said in the middle where it started: 'This room, today: blue five, yellow three, red two, green one — and two changers, whose eyes looked twice. Nobody was wrong, nobody was recruited, and every corner was waved at by every other. When somebody new joins this room, the colours will be the first thing we show them: choose one, stand in it, be waved at. It is the quickest way we know to be a person in a new room.' The mats stay down through the day as the room's quiet geography — children will drift to their colours at odd moments, and the record lets them: a corner chosen in the morning is a place to stand in all day."],
      "A two-colour version: red and blue only, two corners, the whole record inside ten minutes for the very newest groups — choosing between two is already choosing.",
      "A family version: the colours are chosen for somebody else first — 'walk to the colour your grandmother would like' — and the room hears the reasons, which arrive as small stories about people who are not in the room.",
      safety="Choosing is walking, enforced kindly from the first crossing: four directions of travel at once is a small traffic system, and its only rule that matters is pace — a child whose excitement runs is walked back to the middle by the adult's company and sent again at walking pace, without loss of colour or dignity. The mats lie dead flat, corners weighted or taped, edges checked by the adult's own sliding foot before the group gathers: a mat that can skate is a card on the floor or nothing. Corners are furniture-cleared with standing room and a clear wall behind them — no corner sits beside a door that opens into it, a shelf that can be pulled, or the room's traffic lane to the toilet. Nobody is ever left standing alone in a corner as a spectacle: the adult's first choosing plants an adult visibly content in a corner of one, and if the round still produces a corner of one child, the corner-caller's report names it 'a whole corner' before any other size is mentioned.",
      copy_free=True, no_elimination=True,
      inclusion="Choosing is done with the feet when the feet are willing, and at the same size by every other road: a chooser can be carried to their colour by the room's ordinary way of travelling, point at the colour card the adult holds up and be walked the choice by a partner's company, or hold their colour's small card in the middle while the corner waves to THEM — the wave travels both directions in this record, and a corner's people can be counted around a seated chooser exactly as around a standing one. Reasons arrive in any register — a word, a point at something in the room wearing the colour ('blue — like THAT cup'), a held-up card — and changers are honoured identically however the change is announced, including by simply arriving. The corner-callers, who give the room's counts in the official shape, rotate by list and may call from inside their own colour, which is where the authority comes from anyway."),

    # ---------------- Outdoor, just 3 a ninth time (outdoor age-3 primary 13 -> 14) ----------------
    A("big-mud-pie-bakery-morning", "Big Mud Pie Bakery Morning",
      "Real mud, big tins, fallen petals for decoration: the bakery opens, the pies are mixed to pie-thickness, served on leaf plates — and never, ever eaten.",
      ["outdoor"], (3, 3), (3, 12), (15, 20), ["outdoor"],
      ["clean garden soil in two big bowls (soil from a bed the adult dug and picked through themselves that morning — no glass, no sharp stones, no animal mess, nothing sprayed; this is the bakery's flour and it is chosen like it)", "a jug of water for the mixing (the bakery's milk — poured by the adult or under the adult's hand, a little at a time)", "big spoons and big pie tins (sturdy spoons that can stir real mud without bending, and a tin per baker — muffin tins, pie dishes, big jar lids)", "fallen decorations (petals, leaves, and small smooth pebbles gathered from the ground that morning — fallen only, adult-checked; nothing picked off a living plant, nothing sharp)"],
      False, "Dig the soil yourself, that morning, from a bed you know: pick it through with your own hands, stone by stone and shard by shard, because what a three-year-old's hands will stir for twenty minutes must first have passed through the adult's. Choose the ground the way the record's honesty requires: a bed that is soil and only soil — no animal fouling (if the neighbourhood's cats use your beds, choose another bed or a bought bag of plain topsoil, and let the bakery's flour come from the bag without apology; the pies do not care, and the bakers must not be asked to). Set the bakery on a table or a big board at the garden's edge — bowls, jug, spoons, tins in a row like a real counter — and put the washing station (a basin of soapy water and a towel, or the hose at a trickle) where the bakers can see it from the counter: in this record, the washing-up is visible from the first minute, as part of the bakery, not as its punishment.",
      ["Open the bakery at full ceremony and say the plain framing: 'The bakery is open. Today we bake mud pies — real mud, mixed by real bakers, in real tins. Mud pies are for LOOKING at, for carrying carefully, for serving on a leaf to a customer who pretends beautifully. They are never — not a crumb, not a lick, not a dare — for eating. Mud is not food. That is the bakery's first law, and it is older than everyone here.' State the remaining laws whole: 'Bakers stir their own bowls and help at the big bowl when asked. Decorations are the fallen ones in the tray — we do not pick the garden; the garden has already dropped what it can spare. Pies travel on their tins, at walking pace, like pies in a good bakery always travel.'",
       "First mixing together, at the big bowl: the adult puts the first spoonfuls of soil in and the bakers take the spoon in turn, while the water goes in a little at a time from the jug — the adult's hand on it or guiding — and the record's one piece of bakery science is taught by the spoon itself: 'Too dry — it crumbles. It will not hold a pie. More water... now watch — TOO wet, it pours like soup. A pie must hold the spoon's mark —' (draw the spoon through and show the groove staying) '— THERE. Pie-thickness. The groove stays. That is how bakers know, in every bakery there is: the mixture tells you, if you watch it.' Every baker stirs the big bowl at pie-thickness at least once, feeling the exact heaviness through the spoon, because the morning's whole skill lives in that groove.",
       "Baking round: bakers fill their own tins from the big bowl — spoon, spoon, pat flat with the spoon's back — while the adult walks the counter the way bakers' teachers do, naming the work at full size: 'That pie is filled to the rim and patted smooth — a bakery pie.' A tin that will not hold its mixture gets the counter's remedy, not a verdict: back to the big bowl, a spoon of dry soil or a splash of water, stir, and fill again — the record's line for it said in the open: 'Bakers fix mixtures. Mixtures are allowed to need fixing.' When every tin is filled and patted, the decorating tray comes down the counter and the pies are dressed: petals pressed flat in a ring, a pebble stood in the middle like a cherry — pressed IN, gently, because pressing hard is mixing again.",
       "Serving stretch, the bakery's parade: the finished pies are carried — on their tins, two hands, walking pace — to the serving log or step at the garden's edge, and laid on leaf plates the bakers choose from the fallen tray's biggest leaves. Customers are received at the serving place in the room's best pretend: the adult first, ordering gravely ('One mud pie, please — the one with the petal ring'), being served with ceremony, admiring it at length, and returning it uneaten with the bakery's official compliment: 'A beautiful pie. My eyes are full.' Children take the customer chair in turn, ordering by describing ('the pie with the STONE in the middle') so the bakers must read their own work to find it — and every pie is served at least once, because a pie unserved is a pie unfinished, and the bakers keep the tally on their fingers.",
       "Finish with the bakery's closing, which is the record's last lesson and is taught as one: 'Bakeries close. The pies go back to the garden — they were the garden all along, wearing tin hats —' (each baker tips their own pie back onto the bed it came from, tin by tin, with a small ceremony the record does not hurry) '— the tins are washed by their bakers —' (the washing station, soapy water, real scrubbing, adult hands helping with the stubborn corners) '— and the bakers are washed to the elbow, because that is what bakers do before they touch anything else.' The tell-back is said at the empty counter: 'The bakery opened, the mixture reached pie-thickness and told us so, every pie was dressed and served and admired — and not one bite was taken, by law and by pride. The garden has its soil back. The bakers keep everything else.'"],
      "A two-baker version: the big bowl and two tins, mixing and one serving inside fifteen minutes — the whole bakery at its smallest honest size.",
      "A rainy-morning version (a covered porch or awning): the bakery sets up under cover with the soil already dug, and the rain, watched from the dry counter, is received as the bakery's weather — bakers like weather.",
      safety="The first law is the record's whole food safety, said in the framing and kept by the adult's eye all morning: mud is never eaten, licked, or tasted — hands that have stirred go to mouths exactly never, and the adult stations themself where the counter's mouths are visible; a baker who needs their hands near their face is walked to the washing station kindly, washed, and welcomed back — the law has no shame in it, only soap. The soil itself is the adult's audit: dug or bagged from a known-clean source, hand-picked for glass, shards, sharp stone and any animal mess, and a bed with any doubt about it is simply not the bakery's bed — broken skin on a baker's hands is covered before the mixing starts, or that baker takes the jug, the tray, and the serving honours for the morning, at full size. Washing at the end is with soap, to the elbow, checked by the adult the way the soil was: by looking, carefully, at every hand.",
      copy_free=True, no_elimination=True,
      inclusion="The bakery's jobs stand open at every reach: stirring can be two-handed, one-handed with the bowl steadied by a partner, or done by direction — 'stir... slower... the groove — THERE, stop' — with the thickness judged by the director's eyes on the spoon's mark, which is the skill itself. The jug-keeper holds the morning's most trusted honour (water decides everything in a bakery) and pours at the mixer's word from any position at the counter. Decorating is placing, at any scale of movement, including placing by description while a partner's fingers press — the design, the ring of petals, stays the designer's. Serving can be done seated at the serving place as the bakery's host — receiving customers, taking orders by description, giving the official compliment — a job with no carrying in it at all and the whole parade passing through it. The customer chair, rotated by list, belongs to everybody, and an order given in any register — a point at the petal-ring pie — is taken at full ceremony."),
]

# NO NEW COLLECTION this wave, by decision, recorded here and in
# the WAVELOG: the build validator requires 8-12 picks per
# collection, and this pack is honestly six records. A ninth-time
# shelf would need two padded picks or a lowered bar; the wave
# takes neither pass. Collections stay at 27, every earlier
# Little Hands shelf intact at 12 picks.

def tokens(s):
    return set(re.findall(r"[a-z0-9]+", s.lower()))


def main():
    path = os.path.join(DATA, "activities.json")
    acts = json.load(open(path))
    existing = {a["id"] for a in acts}
    corpus = [(a["id"], tokens(a["name"] + " " + a["tagline"])) for a in acts]
    for rec in PACK:
        t = tokens(rec["name"] + " " + rec["tagline"])
        worst, wid = 0.0, None
        for oid, ot in corpus:
            j = len(t & ot) / max(1, len(t | ot))
            if j > worst:
                worst, wid = j, oid
        print(f"jaccard {rec['id']}: worst {worst:.2f} vs {wid}")
        assert worst < 0.55, f"near-duplicate: {rec['id']} vs {wid} ({worst:.2f})"
        assert rec["age_min"] == 3 and rec["age_max"] == 3, f"not 3-only: {rec['id']}"
        assert len(rec["tagline"]) <= 160, f"tagline too long: {rec['id']} ({len(rec['tagline'])})"
    added = 0
    for rec in PACK:
        if rec["id"] in existing:
            print("skip (exists):", rec["id"])
            continue
        acts.append(rec)
        existing.add(rec["id"])
        added += 1
    json.dump(acts, open(path, "w"), indent=1, ensure_ascii=False)
    print(f"added {added} activities; total now {len(acts)}")

    print(f"collections: unchanged at 27 (see note above the pack)")


if __name__ == "__main__":
    main()
